<?php

namespace App\Services\Resume;

use App\Models\Resume\ResumeEntity;
use Illuminate\Validation\Rule;

/**
 * Canonical section schema (resources/resume/schema.json, generated by scripts/resume/gen_schema.py; the frontend
 * ships an identical copy). Drives validation, the dashboard forms and the public payload.
 */
class ResumeSchema
{
    private static ?array $schema = null;

    public static function all(): array
    {
        return self::$schema ??= json_decode((string) file_get_contents(resource_path('resume/schema.json')), true);
    }

    /** @return array<string, array> keyed by slug */
    public static function sections(): array
    {
        $out = [];
        foreach (self::all()['sections'] as $s) {
            $out[$s['slug']] = $s;
        }

        return $out;
    }

    public static function section(string $slug): array
    {
        $s = self::sections()[$slug] ?? null;
        abort_if($s === null, 404);

        return $s;
    }

    /** @return class-string<ResumeEntity> */
    public static function model(string $slug): string
    {
        return 'App\\Models\\Resume\\'.self::section($slug)['model'];
    }

    public static function isSingle(string $slug): bool
    {
        return (bool) (self::section($slug)['single'] ?? false);
    }

    /** Column names a field maps to. */
    public static function columns(array $f): array
    {
        if ($f['type'] === 'range') {
            return ['start', 'end', 'is_current'];
        }

        return $f['i18n'] ? [$f['key'].'_fa', $f['key'].'_en'] : [$f['key']];
    }

    /** Laravel validation rules for one section (partial = PATCH semantics). */
    public static function rules(string $slug, bool $partial = false): array
    {
        $s = self::section($slug);
        $rules = ['is_placeholder' => ['sometimes', 'boolean']];
        if (! ($s['single'] ?? false)) {
            $rules['order'] = ['sometimes', 'integer', 'min:0'];
            $rules['visibility'] = ['sometimes', Rule::in(self::all()['visibility'])];
        }
        foreach ($s['fields'] as $f) {
            $base = match ($f['type']) {
                'text', 'color' => ['string', 'max:'.($f['max'] ?? 255)],
                'textarea', 'richtext' => ['string', 'max:20000'],
                'url' => ['string', 'max:500', 'regex:/^(https?:\/\/|mailto:|tel:|\/)/i'],
                'select' => [Rule::in($f['options'])],
                'int' => ['integer', 'min:'.($f['min'] ?? 0), 'max:'.($f['max'] ?? PHP_INT_MAX)],
                'bool' => ['boolean'],
                'media', 'ref' => ['integer', 'min:1'],
                'list' => ['array', 'max:100'],
                'media_list', 'skills' => ['array', 'max:200'],
                'json' => ['array'],
                'date' => ['array'],
                default => [],
            };
            if ($f['type'] === 'range') {
                $rules['start'] = ['nullable', 'array'];
                $rules['end'] = ['nullable', 'array'];
                $rules['is_current'] = ['sometimes', 'boolean'];
                foreach (['start', 'end'] as $k) {
                    $rules[$k.'.g'] = ['nullable', 'string', 'regex:/^\d{4}(-\d{2}(-\d{2})?)?$/'];
                    $rules[$k.'.j'] = ['nullable', 'string', 'regex:/^\d{4}(-\d{2}(-\d{2})?)?$/'];
                    $rules[$k.'.precision'] = ['nullable', Rule::in(['year', 'month', 'day'])];
                }

                continue;
            }
            $cols = self::columns($f);
            foreach ($cols as $i => $col) {
                // A required i18n field needs at least the Persian or English value, not both.
                $req = ($f['required'] ?? false) && ! $partial && ! $f['i18n'] ? 'required' : 'nullable';
                if (($f['required'] ?? false) && ! $partial && $f['i18n']) {
                    $other = $cols[1 - $i];
                    $req = 'required_without:'.$other;
                }
                $rules[$col] = array_merge($partial ? ['sometimes', $req] : [$req], $base);
                if (in_array($f['type'], ['list'], true)) {
                    $rules[$col.'.*'] = ['nullable', 'string', 'max:500'];
                }
                if (in_array($f['type'], ['media_list', 'skills'], true)) {
                    $rules[$col.'.*'] = ['integer', 'min:1'];
                }
                if ($f['type'] === 'date') {
                    $rules[$col.'.g'] = ['nullable', 'string', 'regex:/^\d{4}(-\d{2}(-\d{2})?)?$/'];
                    $rules[$col.'.j'] = ['nullable', 'string', 'regex:/^\d{4}(-\d{2}(-\d{2})?)?$/'];
                    $rules[$col.'.precision'] = ['nullable', Rule::in(['year', 'month', 'day'])];
                }
            }
        }

        return $rules;
    }

    /** Fill in the missing calendar of every ResumeDate in a validated payload. */
    public static function normalize(string $slug, array $data): array
    {
        foreach (self::section($slug)['fields'] as $f) {
            $keys = $f['type'] === 'range' ? ['start', 'end'] : ($f['type'] === 'date' ? self::columns($f) : []);
            foreach ($keys as $k) {
                if (array_key_exists($k, $data)) {
                    $data[$k] = ResumeDate::normalize($data[$k]);
                }
            }
        }
        if (array_key_exists('is_current', $data) && $data['is_current']) {
            $data['end'] = null;
        }

        return $data;
    }

    /** Public payload of one row: hides private fields, keeps both languages. */
    public static function present(string $slug, ResumeEntity $row, bool $admin = false): array
    {
        $s = self::section($slug);
        $out = ['id' => $row->id, 'is_placeholder' => (bool) $row->is_placeholder];
        if (! ($s['single'] ?? false)) {
            $out['order'] = (int) $row->order;
            $out['visibility'] = $row->visibility;
        }
        foreach ($s['fields'] as $f) {
            if (! $admin && ($f['private'] ?? false)) {
                continue;
            }
            if (! $admin && $slug === 'settings' && $f['key'] === 'private_token') {
                continue;
            }
            foreach (self::columns($f) as $col) {
                $out[$col] = $row->getAttribute($col);
            }
            if ($f['type'] === 'range') {
                $out['duration_months'] = ResumeDate::months($row->start, $row->is_current ? null : $row->end);
            }
        }

        return $out;
    }
}
